public final class SecureHandler extends java.util.logging.Handler {
    private final Mac prepared;                          // HmacSHA256, initialised with the key
    private byte[] prev = new byte[0]; private long seq;
    public void flush() { } public void close() { }
    public synchronized void publish(LogRecord r) {
        byte[] body = canonicalise(r);                   // redact + stable order; message is data
        Mac m = (Mac) prepared.clone();                  // cheaper than init() per record
        m.update(prev); m.update(longToBytes(seq)); m.update(body);
        prev = m.doFinal();
        sink.append(seq++, prev, body);                  // append-only file, fsync per policy
    }
}
